CREATE OR REPLACE FUNCTION public.lite3_counter_context223(p_product_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p public.products;family BOOLEAN;rows JSONB;
BEGIN
 PERFORM sales_lite3.assert_owner223();
 SELECT * INTO p FROM public.products WHERE id=p_product_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'QUANTITY223_PRODUCT_REQUIRED';END IF;
 family:=p.is_flavor_master OR EXISTS(SELECT 1 FROM public.products c WHERE c.flavor_master_product_id=p.id);
 -- Never label a previously tracked quantity with a different base unit.
 IF EXISTS(SELECT 1 FROM public.products leaf JOIN sales_lite3.quantity_counters c ON c.product_id=leaf.id
  WHERE c.ever_enabled AND c.unit_id IS DISTINCT FROM leaf.unit_id
  AND((NOT family AND leaf.id=p.id) OR(family AND leaf.flavor_master_product_id=p.id))) THEN
  RAISE EXCEPTION 'QUANTITY223_UNIT_REVIEW_REQUIRED';
 END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object(
  'productId',leaf.id,'name',leaf.name_ar,'flavorName',leaf.flavor_name_ar,'sku',leaf.sku,
  'unitId',leaf.unit_id,'unitName',COALESCE(u.name_ar,'باكيت'),
  'enabled',COALESCE(c.enabled,false),'quantity',COALESCE(c.quantity,0),
  'threshold',COALESCE(c.low_threshold,0),'revision',COALESCE(c.revision,0),
  'everEnabled',COALESCE(c.ever_enabled,false),'active',leaf.is_active,
  'manualAvailable',COALESCE(sales_lite1.available(leaf.id),false),
  'effectiveAvailable',COALESCE(sales_lite1.available(leaf.id),false) AND(NOT COALESCE(c.enabled,false) OR c.quantity>0)
 ) ORDER BY leaf.sku,leaf.id),'[]') INTO rows
 FROM public.products leaf LEFT JOIN public.units u ON u.id=leaf.unit_id
 LEFT JOIN sales_lite3.quantity_counters c ON c.product_id=leaf.id
 WHERE NOT leaf.is_flavor_master AND((NOT family AND leaf.id=p.id) OR(family AND leaf.flavor_master_product_id=p.id));
 IF jsonb_array_length(rows)>200 THEN RAISE EXCEPTION 'QUANTITY223_CONTEXT_LIMIT';END IF;
 RETURN jsonb_build_object('contractVersion','optional-quantity223-v1','fullAccounting',false,'productId',p.id,'isFamily',family,'products',rows);
END $function$

CREATE OR REPLACE FUNCTION public.lite3_low_counters223(p_page integer DEFAULT 1, p_page_size integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE rows JSONB;total BIGINT;
BEGIN
 PERFORM sales_lite3.assert_owner223();
 IF p_page IS NULL OR p_page NOT BETWEEN 1 AND 100000 OR p_page_size IS NULL OR p_page_size NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'QUANTITY223_PAGE_INVALID';END IF;
 SELECT count(*) INTO total FROM sales_lite3.quantity_counters c JOIN public.products p ON p.id=c.product_id
 WHERE c.enabled AND p.is_active AND NOT p.is_flavor_master AND(c.quantity=0 OR c.quantity<c.low_threshold);
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.quantity,x."productId"),'[]') INTO rows FROM(
  SELECT p.id AS "productId",p.sku,p.name_ar AS name,COALESCE(u.name_ar,'باكيت') AS "unitName",c.quantity,c.low_threshold AS threshold,c.revision
  FROM sales_lite3.quantity_counters c JOIN public.products p ON p.id=c.product_id LEFT JOIN public.units u ON u.id=c.unit_id
  WHERE c.enabled AND p.is_active AND NOT p.is_flavor_master AND(c.quantity=0 OR c.quantity<c.low_threshold)
  ORDER BY c.quantity,p.id LIMIT p_page_size OFFSET(p_page-1)::BIGINT*p_page_size
 ) x;
 RETURN jsonb_build_object('contractVersion','optional-quantity223-v1','products',rows,'total',total,'page',p_page,'pageSize',p_page_size);
END $function$

CREATE OR REPLACE FUNCTION public.lite3_set_counter223(p_product_id uuid, p_enabled boolean, p_quantity bigint, p_low_threshold bigint, p_expected_revision bigint, p_key uuid, p_expected_unit_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
DECLARE p public.products;c sales_lite3.quantity_counters;r sales_lite3.quantity_requests;
 fingerprint TEXT;result JSONB;old_configuration JSONB;new_configuration JSONB;unit_name TEXT;
 old_revision BIGINT;old_quantity BIGINT;next_revision BIGINT;ever_enabled BOOLEAN;low_sent BOOLEAN;zero_sent BOOLEAN;
BEGIN
 PERFORM sales_lite3.assert_owner223();PERFORM sales_lite1.lock_mode();
 IF NOT sales_lite1.enabled() THEN RAISE EXCEPTION 'QUANTITY223_OFF_REQUIRED';END IF;
 IF p_product_id IS NULL OR p_key IS NULL OR p_expected_unit_id IS NULL OR p_enabled IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0
 OR p_quantity IS NULL OR p_quantity NOT BETWEEN 0 AND 1000000000
 OR p_low_threshold IS NULL OR p_low_threshold NOT BETWEEN 0 AND 1000000000 THEN
  RAISE EXCEPTION 'QUANTITY223_INPUT_INVALID: أدخل كمية وحدّ تنبيه صحيحين وغير سالبين.';
 END IF;
 fingerprint:=encode(extensions.digest(jsonb_build_object('product',p_product_id,'enabled',p_enabled,'quantity',p_quantity,'threshold',p_low_threshold,'revision',p_expected_revision,'unit',p_expected_unit_id)::TEXT,'sha256'),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('optional-quantity223:'||p_key::TEXT,0));
 SELECT * INTO r FROM sales_lite3.quantity_requests WHERE key=p_key;
 IF FOUND THEN
  IF r.actor_id IS DISTINCT FROM auth.uid() OR r.fingerprint<>fingerprint THEN RAISE EXCEPTION 'QUANTITY223_IDEMPOTENCY_CONFLICT';END IF;
  RETURN r.result||jsonb_build_object('idempotentReplay',true);
 END IF;
 SELECT * INTO p FROM public.products WHERE id=p_product_id FOR UPDATE;
 IF NOT FOUND OR p.is_flavor_master OR EXISTS(SELECT 1 FROM public.products child WHERE child.flavor_master_product_id=p.id) THEN
  RAISE EXCEPTION 'QUANTITY223_SELLABLE_PRODUCT_REQUIRED: عدّاد مستقل للمنتج القابل للبيع أو لكل نكهة؛ لا يُفعّل للأب.';
 END IF;
 IF p.unit_id IS DISTINCT FROM p_expected_unit_id THEN
  RAISE EXCEPTION 'QUANTITY223_PRODUCT_UNIT_CHANGED: تغيّرت وحدة الأساس منذ قراءتها؛ أعد القراءة قبل حفظ الكمية.';
 END IF;
 SELECT * INTO c FROM sales_lite3.quantity_counters WHERE product_id=p.id FOR UPDATE;
 old_revision:=COALESCE(c.revision,0);old_quantity:=COALESCE(c.quantity,0);
 IF old_revision<>p_expected_revision THEN RAISE EXCEPTION 'QUANTITY223_CONFLICT: تغيّرت الكمية منذ قراءتها؛ أعد القراءة قبل تعديلها.';END IF;
 IF COALESCE(c.ever_enabled,false) AND c.unit_id IS DISTINCT FROM p.unit_id THEN
  RAISE EXCEPTION 'QUANTITY223_UNIT_REVIEW_REQUIRED';
 END IF;
 SELECT COALESCE(name_ar,'باكيت') INTO unit_name FROM public.units WHERE id=p.unit_id;
 next_revision:=old_revision+1;ever_enabled:=COALESCE(c.ever_enabled,false) OR p_enabled;
 low_sent:=CASE WHEN NOT p_enabled OR p_low_threshold=0 OR p_quantity>=p_low_threshold THEN false ELSE COALESCE(c.low_sent,false) END;
 zero_sent:=CASE WHEN NOT p_enabled OR p_quantity>0 THEN false ELSE COALESCE(c.zero_sent,false) END;
 old_configuration:=jsonb_build_object('enabled',COALESCE(c.enabled,false),'threshold',COALESCE(c.low_threshold,0),'unitId',COALESCE(c.unit_id,p.unit_id));
 new_configuration:=jsonb_build_object('enabled',p_enabled,'threshold',p_low_threshold,'unitId',p.unit_id);
 INSERT INTO sales_lite3.quantity_counters(product_id,unit_id,enabled,quantity,low_threshold,revision,ever_enabled,low_sent,zero_sent,updated_by)
 VALUES(p.id,p.unit_id,p_enabled,p_quantity,p_low_threshold,next_revision,ever_enabled,low_sent,zero_sent,auth.uid())
 ON CONFLICT(product_id) DO UPDATE SET unit_id=excluded.unit_id,enabled=excluded.enabled,quantity=excluded.quantity,
  low_threshold=excluded.low_threshold,revision=excluded.revision,ever_enabled=excluded.ever_enabled,
  low_sent=excluded.low_sent,zero_sent=excluded.zero_sent,updated_by=excluded.updated_by,updated_at=clock_timestamp();
 INSERT INTO sales_lite3.quantity_events(product_id,sku_snapshot,name_snapshot,unit_id,unit_name_snapshot,kind,source_type,source_id,
  quantity_before,quantity_after,requested_quantity,applied_quantity,shortage_quantity,revision_before,revision_after,configuration_before,configuration_after,created_by)
 VALUES(p.id,p.sku,p.name_ar,p.unit_id,COALESCE(unit_name,'باكيت'),'manual','quantity_request',p_key,
  old_quantity,p_quantity,p_quantity,abs(p_quantity-old_quantity),0,old_revision,next_revision,old_configuration,new_configuration,auth.uid());
 INSERT INTO public.audit_logs(user_id,action,entity_name,entity_id,details)
 VALUES(auth.uid(),'SET_OPTIONAL_QUANTITY','products',p.id,jsonb_build_object('before',old_configuration||jsonb_build_object('quantity',old_quantity,'revision',old_revision),
  'after',new_configuration||jsonb_build_object('quantity',p_quantity,'revision',next_revision),'requestKey',p_key));
 result:=jsonb_build_object('success',true,'idempotentReplay',false,'productId',p.id,'unitId',p.unit_id,'enabled',p_enabled,'quantity',p_quantity,'threshold',p_low_threshold,'revision',next_revision);
 INSERT INTO sales_lite3.quantity_requests(key,actor_id,fingerprint,result) VALUES(p_key,auth.uid(),fingerprint,result);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION sales_lite3.alert_transition223()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE event_type TEXT;p public.products;unit_name TEXT;changed BOOLEAN;
BEGIN
 IF NOT sales_lite1.enabled() OR NOT NEW.enabled THEN RETURN NEW;END IF;
 changed:=TG_OP='INSERT';
 IF TG_OP='UPDATE' THEN changed:=NOT OLD.enabled OR NEW.quantity<OLD.quantity OR NEW.low_threshold>OLD.low_threshold;END IF;
 IF NOT changed THEN RETURN NEW;END IF;
 IF NEW.quantity=0 AND NOT NEW.zero_sent THEN event_type:='out_of_stock';
 ELSIF NEW.quantity>0 AND NEW.low_threshold>0 AND NEW.quantity<NEW.low_threshold AND NOT NEW.low_sent THEN event_type:='low_stock';
 ELSE RETURN NEW;END IF;
 SELECT * INTO STRICT p FROM public.products WHERE id=NEW.product_id;
 SELECT COALESCE(name_ar,'باكيت') INTO unit_name FROM public.units WHERE id=NEW.unit_id;
 PERFORM public.enqueue_automation_event('quantity223:'||event_type||':'||NEW.product_id::TEXT||':'||NEW.revision::TEXT,event_type,NEW.product_id,
  jsonb_build_object('audience','owner','quantitySource','sales_only_counter','accountingTracked',false,
   'productId',p.id,'productName',p.name_ar,'sku',p.sku,'availableQuantity',NEW.quantity,'unitName',COALESCE(unit_name,'باكيت'),'thresholdQuantity',NEW.low_threshold));
 UPDATE sales_lite3.quantity_counters SET low_sent=true,zero_sent=CASE WHEN event_type='out_of_stock' THEN true ELSE zero_sent END
 WHERE product_id=NEW.product_id;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION sales_lite3.assert_owner223()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$ BEGIN
 IF auth.role() IS DISTINCT FROM 'authenticated' OR auth.jwt()->>'aal' IS DISTINCT FROM 'aal2' THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='QUANTITY223_OWNER_AAL2_REQUIRED';
 END IF;
 PERFORM public.assert_erp_role(ARRAY['owner'],'إدارة عدّاد الكمية الاختياري');
 IF NOT sales_lite1.enabled() THEN RAISE EXCEPTION 'QUANTITY223_OFF_REQUIRED';END IF;
END $function$

CREATE OR REPLACE FUNCTION sales_lite3.cancel_credit223()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r RECORD;c sales_lite3.quantity_counters;p public.products;configuration JSONB;unit_name TEXT;
BEGIN
 IF NOT sales_lite1.enabled() OR NEW.status IS NOT DISTINCT FROM OLD.status OR NEW.status<>'cancelled'
 OR NOT sales_lite1.is_order(NEW.id) THEN RETURN NEW;END IF;
 -- A full order has no new provenance and returns above without any effect.
 -- Product locking follows the same UUID order as creation/manual correction.
 FOR r IN
  SELECT product_id,sum(applied_quantity)::BIGINT AS quantity FROM sales_lite3.quantity_events
  WHERE order_id=NEW.id AND kind='sale' GROUP BY product_id ORDER BY product_id
 LOOP
  IF EXISTS(SELECT 1 FROM sales_lite3.quantity_events WHERE kind='cancel' AND source_type='order_cancel' AND source_id=NEW.id AND product_id=r.product_id) THEN
   RAISE EXCEPTION 'QUANTITY223_DUPLICATE_CANCEL';
  END IF;
  SELECT * INTO STRICT p FROM public.products WHERE id=r.product_id FOR UPDATE;
  SELECT * INTO STRICT c FROM sales_lite3.quantity_counters WHERE product_id=r.product_id FOR UPDATE;
  IF c.unit_id IS DISTINCT FROM p.unit_id THEN RAISE EXCEPTION 'QUANTITY223_UNIT_REVIEW_REQUIRED';END IF;
  SELECT COALESCE(name_ar,'باكيت') INTO unit_name FROM public.units WHERE id=c.unit_id;
  configuration:=jsonb_build_object('enabled',c.enabled,'threshold',c.low_threshold,'unitId',c.unit_id);
  UPDATE sales_lite3.quantity_counters SET quantity=c.quantity+r.quantity,revision=c.revision+1,
   low_sent=CASE WHEN c.quantity+r.quantity>=c.low_threshold THEN false ELSE c.low_sent END,
   zero_sent=CASE WHEN c.quantity+r.quantity>0 THEN false ELSE c.zero_sent END,
   updated_by=auth.uid(),updated_at=clock_timestamp() WHERE product_id=r.product_id;
  INSERT INTO sales_lite3.quantity_events(product_id,sku_snapshot,name_snapshot,unit_id,unit_name_snapshot,kind,source_type,source_id,order_id,
   quantity_before,quantity_after,requested_quantity,applied_quantity,shortage_quantity,revision_before,revision_after,configuration_before,configuration_after,created_by)
  VALUES(p.id,p.sku,p.name_ar,c.unit_id,COALESCE(unit_name,'باكيت'),'cancel','order_cancel',NEW.id,NEW.id,
   c.quantity,c.quantity+r.quantity,r.quantity,r.quantity,0,c.revision,c.revision+1,configuration,configuration,auth.uid());
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION sales_lite3.component_debit223()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE order_id UUID;
BEGIN
 IF NOT sales_lite1.enabled() THEN RETURN NEW;END IF;
 SELECT i.order_id INTO STRICT order_id FROM public.order_parcel_instances i WHERE i.id=NEW.parcel_instance_id;
 PERFORM sales_lite3.consume223(order_id,NEW.product_id,NEW.base_quantity,'parcel_component',NEW.id);
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION sales_lite3.confirm_plan223(p_plan jsonb, p_existing uuid[], p_confirmed jsonb)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r RECORD;confirmed UUID[]:=p_existing;
BEGIN
 FOR r IN
  SELECT required.product_id,required.required_quantity,c.quantity FROM sales_lite3.plan_quantities223(p_plan) required
  JOIN sales_lite3.quantity_counters c ON c.product_id=required.product_id AND c.enabled
  WHERE required.required_quantity>c.quantity ORDER BY required.product_id
 LOOP
  IF NOT COALESCE(p_confirmed @> jsonb_build_array(r.product_id),false) THEN
   RAISE EXCEPTION 'LITE1_UNAVAILABLE_CONFIRM_REQUIRED: QUANTITY223_SHORTAGE';
  END IF;
  IF NOT r.product_id=ANY(COALESCE(confirmed,'{}'::UUID[])) THEN confirmed:=array_append(confirmed,r.product_id);END IF;
 END LOOP;
 RETURN confirmed;
END $function$

CREATE OR REPLACE FUNCTION sales_lite3.consume223(p_order uuid, p_product uuid, p_quantity bigint, p_source_type text, p_source_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c sales_lite3.quantity_counters;p public.products;o public.orders;
 available BIGINT;shortage BIGINT;proof UUID[];unit_name TEXT;configuration JSONB;
BEGIN
 IF NOT sales_lite1.enabled() OR NOT sales_lite1.is_order(p_order) THEN RETURN;END IF;
 IF p_quantity IS NULL OR p_quantity<=0 THEN RAISE EXCEPTION 'QUANTITY223_SALE_QUANTITY_INVALID';END IF;
 SELECT * INTO STRICT p FROM public.products WHERE id=p_product FOR UPDATE;
 SELECT * INTO c FROM sales_lite3.quantity_counters WHERE product_id=p_product FOR UPDATE;
 IF NOT FOUND OR NOT c.enabled THEN RETURN;END IF;
 IF c.unit_id IS DISTINCT FROM p.unit_id THEN RAISE EXCEPTION 'QUANTITY223_UNIT_REVIEW_REQUIRED';END IF;
 IF EXISTS(SELECT 1 FROM sales_lite3.quantity_events WHERE kind='sale' AND source_type=p_source_type AND source_id=p_source_id AND product_id=p_product) THEN
  RAISE EXCEPTION 'QUANTITY223_DUPLICATE_DEBIT';
 END IF;
 SELECT * INTO STRICT o FROM public.orders WHERE id=p_order;
 shortage:=GREATEST(p_quantity-c.quantity,0);available:=LEAST(p_quantity,c.quantity);
 IF shortage>0 THEN
  IF o.source='website' THEN RAISE EXCEPTION 'QUANTITY223_INSUFFICIENT';END IF;
  IF o.source<>'pos' THEN RAISE EXCEPTION 'QUANTITY223_SOURCE_INVALID';END IF;
  SELECT unavailable_confirmed INTO STRICT proof FROM sales_lite1.orders WHERE order_id=o.id;
  IF NOT COALESCE(p_product=ANY(proof),false) THEN RAISE EXCEPTION 'LITE1_UNAVAILABLE_CONFIRM_REQUIRED: QUANTITY223_SHORTAGE';END IF;
 END IF;
 SELECT COALESCE(name_ar,'باكيت') INTO unit_name FROM public.units WHERE id=c.unit_id;
 configuration:=jsonb_build_object('enabled',c.enabled,'threshold',c.low_threshold,'unitId',c.unit_id);
 UPDATE sales_lite3.quantity_counters SET quantity=c.quantity-available,revision=c.revision+1,updated_by=auth.uid(),updated_at=clock_timestamp() WHERE product_id=p_product;
 INSERT INTO sales_lite3.quantity_events(product_id,sku_snapshot,name_snapshot,unit_id,unit_name_snapshot,kind,source_type,source_id,order_id,
  quantity_before,quantity_after,requested_quantity,applied_quantity,shortage_quantity,revision_before,revision_after,configuration_before,configuration_after,created_by)
 VALUES(p.id,p.sku,p.name_ar,c.unit_id,COALESCE(unit_name,'باكيت'),'sale',p_source_type,p_source_id,o.id,
  c.quantity,c.quantity-available,p_quantity,available,shortage,c.revision,c.revision+1,configuration,configuration,auth.uid());
 IF shortage>0 THEN
  INSERT INTO public.audit_logs(user_id,action,entity_name,entity_id,details)
  VALUES(auth.uid(),'OPTIONAL_QUANTITY_SHORTAGE','orders',o.id,jsonb_build_object('productId',p.id,'requested',p_quantity,'before',c.quantity,'deducted',available,'unavailableConfirmed',true,'shortage',shortage));
 END IF;
END $function$

CREATE OR REPLACE FUNCTION sales_lite3.guard_base_unit223()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$ BEGIN
 IF NOT sales_lite1.enabled() OR NEW.unit_id IS NOT DISTINCT FROM OLD.unit_id THEN RETURN NEW;END IF;
 IF EXISTS(SELECT 1 FROM sales_lite3.quantity_counters c WHERE c.ever_enabled
  AND(c.product_id=OLD.id OR EXISTS(SELECT 1 FROM public.products leaf WHERE leaf.id=c.product_id AND leaf.flavor_master_product_id=OLD.id))) THEN
  RAISE EXCEPTION 'QUANTITY223_BASE_UNIT_FROZEN: وحدة الأساس ثابتة بعد تفعيل العدّاد؛ يمكنك إضافة طرد أو تعديل عدده وأسعاره.';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION sales_lite3.return_credit223()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE oid UUID;r RECORD;c sales_lite3.quantity_counters;p public.products;configuration JSONB;unit_name TEXT;
BEGIN
 IF NOT sales_lite1.enabled() THEN RETURN NEW;END IF;
 SELECT order_id INTO STRICT oid FROM sales_lite1.returns WHERE id=NEW.return_id;
 IF NOT sales_lite1.is_order(oid) THEN RETURN NEW;END IF;
 FOR r IN SELECT(source->>'product_id')::UUID AS product_id,sum((source->>'sellable_restock_quantity')::BIGINT)::BIGINT AS quantity
  FROM jsonb_array_elements(NEW.request_snapshot->'physicalSources') source
  WHERE(source->>'sellable_restock_quantity')::BIGINT>0
  AND EXISTS(SELECT 1 FROM sales_lite3.quantity_events e WHERE e.kind='sale' AND e.order_id=oid AND e.product_id=(source->>'product_id')::UUID)
  GROUP BY(source->>'product_id')::UUID ORDER BY(source->>'product_id')::UUID
 LOOP
  SELECT * INTO STRICT p FROM public.products WHERE id=r.product_id FOR UPDATE;
  SELECT * INTO STRICT c FROM sales_lite3.quantity_counters WHERE product_id=r.product_id FOR UPDATE;
  IF c.unit_id IS DISTINCT FROM p.unit_id OR EXISTS(SELECT 1 FROM sales_lite3.quantity_events e WHERE e.kind='sale' AND e.order_id=oid AND e.product_id=r.product_id AND e.unit_id IS DISTINCT FROM c.unit_id) THEN
   RAISE EXCEPTION 'QUANTITY223_UNIT_REVIEW_REQUIRED';
  END IF;
  SELECT COALESCE(name_ar,'باكيت') INTO unit_name FROM public.units WHERE id=c.unit_id;
  configuration:=jsonb_build_object('enabled',c.enabled,'threshold',c.low_threshold,'unitId',c.unit_id);
  UPDATE sales_lite3.quantity_counters SET quantity=c.quantity+r.quantity,revision=c.revision+1,
   low_sent=CASE WHEN c.quantity+r.quantity>=c.low_threshold THEN false ELSE c.low_sent END,
   zero_sent=CASE WHEN c.quantity+r.quantity>0 THEN false ELSE c.zero_sent END,
   updated_by=auth.uid(),updated_at=clock_timestamp() WHERE product_id=r.product_id;
  INSERT INTO sales_lite3.quantity_events(product_id,sku_snapshot,name_snapshot,unit_id,unit_name_snapshot,kind,source_type,source_id,order_id,
   quantity_before,quantity_after,requested_quantity,applied_quantity,shortage_quantity,revision_before,revision_after,configuration_before,configuration_after,created_by)
  VALUES(p.id,p.sku,p.name_ar,c.unit_id,COALESCE(unit_name,'باكيت'),'return','customer_return',NEW.return_id,oid,
   c.quantity,c.quantity+r.quantity,r.quantity,r.quantity,0,c.revision,c.revision+1,configuration,configuration,auth.uid());
 END LOOP;
 RETURN NEW;
END $function$
